"""
Unit tests for NVIDIA PTX Parser and Inspection Engine
"""

import unittest
import os
import sys

sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), "..", "python")))

from kernelguard.analysis.ptx_parser import PtxParser, verify_ptx_assertions


SAMPLE_PTX_SAXPY = """
//
// Generated by NVIDIA NVCC
//

.version 7.5
.target sm_75
.address_size 64

.visible .entry saxpy_cuda_kernel(
    .param .f32 saxpy_cuda_kernel_param_0,
    .param .u64 saxpy_cuda_kernel_param_1,
    .param .u64 saxpy_cuda_kernel_param_2,
    .param .u64 saxpy_cuda_kernel_param_3,
    .param .u64 saxpy_cuda_kernel_param_4
)
{
    .reg .pred  %p<2>;
    .reg .f32   %f<5>;
    .reg .b32   %r<4>;
    .reg .b64   %rd<11>;

    ld.param.f32    %f1, [saxpy_cuda_kernel_param_0];
    ld.param.u64    %rd1, [saxpy_cuda_kernel_param_1];
    ld.param.u64    %rd2, [saxpy_cuda_kernel_param_2];
    ld.param.u64    %rd3, [saxpy_cuda_kernel_param_3];
    ld.param.u64    %rd4, [saxpy_cuda_kernel_param_4];

    mov.u32         %r1, %ctaid.x;
    mov.u32         %r2, %ntid.x;
    mov.u32         %r3, %tid.x;
    mad.lo.s32      %r1, %r1, %r2, %r3;

    setp.ge.u64     %p1, %rd5, %rd4;
    @%p1 bra        $L__BB0_2;

    ld.global.f32   %f2, [%rd7];
    ld.global.f32   %f3, [%rd9];
    fma.rn.f32      %f4, %f1, %f2, %f3;
    st.global.f32   [%rd10], %f4;

$L__BB0_2:
    ret;
}
"""

SAMPLE_PTX_VEC_ADD = """
.version 7.5
.target sm_75
.address_size 64

.visible .entry vec_add_cuda_kernel(
    .param .u64 p0,
    .param .u64 p1,
    .param .u64 p2,
    .param .u64 p3
)
{
    .reg .f32   %f<4>;
    .reg .b64   %rd<6>;

    ld.global.f32   %f1, [%rd1];
    ld.global.f32   %f2, [%rd2];
    add.f32         %f3, %f1, %f2;
    st.global.f32   [%rd3], %f3;
    ret;
}
"""


class TestPtxParser(unittest.TestCase):
    def test_parse_header_and_directives(self):
        report = PtxParser.parse_string(SAMPLE_PTX_SAXPY)
        self.assertEqual(report.version, "7.5")
        self.assertEqual(report.target_arch, "sm_75")
        self.assertEqual(report.address_size, 64)

    def test_parse_functions_and_registers(self):
        report = PtxParser.parse_string(SAMPLE_PTX_SAXPY)
        self.assertIn("saxpy_cuda_kernel", report.functions)
        func = report.functions["saxpy_cuda_kernel"]
        self.assertTrue(func.is_entry)
        self.assertEqual(func.registers.get(".f32"), 5)
        self.assertEqual(func.registers.get(".b64"), 11)

    def test_parse_instructions_and_histograms(self):
        report = PtxParser.parse_string(SAMPLE_PTX_SAXPY)
        self.assertIn("fma", report.instruction_histogram)
        self.assertIn("fma.rn.f32", report.instruction_histogram)
        self.assertEqual(report.instruction_histogram["fma.rn.f32"], 1)
        self.assertGreater(report.instruction_histogram["ld.param"], 0)

    def test_verify_assertions_success(self):
        report = PtxParser.parse_string(SAMPLE_PTX_SAXPY)
        passed, msgs = verify_ptx_assertions(
            report,
            expected_instructions=["fma.rn.f32", "st.global.f32"],
            forbidden_instructions=["atom.global"]
        )
        self.assertTrue(passed)

    def test_verify_assertions_failure(self):
        report = PtxParser.parse_string(SAMPLE_PTX_VEC_ADD)
        passed, msgs = verify_ptx_assertions(
            report,
            expected_instructions=["fma.rn.f32"],  # vec_add has add.f32, not fma
        )
        self.assertFalse(passed)


if __name__ == "__main__":
    unittest.main()
